def congruence_inertia(matrix: sp.MatrixBase) -> tuple[int, int, int]:
    """Exact (n_positive, n_zero, n_negative) WITH multiplicity, by congruence.

    Delegated to the COMMITTED Block 144 helper through the Block 159/158/156
    import chain, so the tool this block reasons with is exactly the blob Block
    159's gate A pins.  It is called on EXACT algebraic matrices only.
    """
