HERMITICITY_COMMITTED_RANK = 16
POOL_TWO_LEADS = 2

RUNTIME_BUDGET_SEC = 150


# ---------------------------------------------------------------------------
# constructions.  Everything below is built from the committed primitives.
# ---------------------------------------------------------------------------
def residue(differential: sp.Matrix, hodge: sp.Matrix, mass=sp.Integer(0)):
    """K = quotient(m H + i(H d + d^dagger H)); the committed routine."""
    return b145.quotient_action(differential, hodge, mass)


def cover_move(label):
    return b148.move_matrix(b148.move_permutation(label))


def single_hop(target: int, source: int, value) -> sp.Matrix:
    out = sp.zeros(SIZE, SIZE)
    out[target, source] = value
    return out


def crossing_operator(columns, weight_of) -> sp.Matrix:
    """The temporal boundary-crossing hops on the given spatial columns.

    Cover hops (1,x) <- (2,x) and (3,x) <- (4,x), antiperiodically imaged.
    Every one of them lies in the committed displacement class (-1, 0) and
    inside the committed probe edge's own 48-hop support, so restricting to
    them is a LINK DELETION and never a support widening.
    """
    out = sp.zeros(SIZE, SIZE)
    for x in columns:
        for target_t, source_t in ((1, 2), (3, 4)):
            p, q = cover_index(target_t, x), cover_index(source_t, x)
            out[p, q] = weight_of(x)
            out[(p + PHYS) % SIZE, (q + PHYS) % SIZE] = weight_of(x)
    return out


def restrict(operator: sp.Matrix, mask: sp.Matrix) -> sp.Matrix:
    out = sp.zeros(SIZE, SIZE)
    for p in range(SIZE):
        for q in range(SIZE):
            if mask[p, q] != 0:
                out[p, q] = operator[p, q]
    return out


def antiperiodic_key(p: int, q: int) -> tuple[int, int]:
    a, b = p, q
    if a >= PHYS and b >= PHYS:
        a, b = a - PHYS, b - PHYS
    elif a >= PHYS > b:
        a, b = a - PHYS, b + PHYS
    return (a, b)


def tied_family(mask: sp.Matrix, tag: str = "w"):
    """Free entrywise complex reweighting of a support, tied by the two
    antiperiodicity laws the committed differential is MEASURED to obey."""
    symbols, representative = {}, {}
    out = sp.zeros(SIZE, SIZE)
    for p in range(SIZE):
        for q in range(SIZE):
            if mask[p, q] != 0:
                key = antiperiodic_key(p, q)
                if key not in symbols:
                    index = len(symbols)
                    symbols[key] = (
                        sp.Symbol(f"r{tag}{index}", real=True)
                        + sp.I * sp.Symbol(f"s{tag}{index}", real=True)
                    )
                    representative[key] = (index, (p, q))
                out[p, q] = symbols[key]
    return out, symbols, representative


def displacement(index: int) -> tuple[int, int]:
    p, q = divmod(index, SIZE)
    return (
        (cover_site(p)[0] - cover_site(q)[0]) % COVER_T,
        (cover_site(p)[1] - cover_site(q)[1]) % LX,
    )


def odd_time_field(shear, volume) -> dict:
    return {
        (t, x): (shear if t % 2 else sp.Integer(0), volume)
        for t in range(4)
        for x in range(4)
    }


def staggered_field(shear, volume) -> dict:
    return {
        (t, x): (shear if (t + x) % 2 else -shear, volume)
        for t in range(4)
        for x in range(4)
    }


# ---------------------------------------------------------------------------
# measured facts (computed once, before any mutation flag is consulted)
# ---------------------------------------------------------------------------
@dataclass(frozen=True)
class Facts:
    main_head: str
    authority: AuthorityCertificate
    # B: calibration, and the mass channel's diagonality theorem
    calibration: tuple
    diagonality: tuple
    # C: the enumeration -- scalar field, generators, the support law
    linearity: tuple
    support_law: tuple
    committed_classes: tuple
    # D: the committed-support census and the pure link deletion
    census: tuple
    deletion: tuple
    symbolic_form: tuple
    # E: the connection channel's weight-and-centring conspiracy
    conspiracy: tuple
    loci: tuple
    # F: the certificate, the vacuous items, the live reversal, x-selectivity
    witness: tuple
    vacuous: tuple
    cells: tuple
    live_reversal: tuple
    selectivity: tuple
    # G: the cone criterion, the mass reversal, the Hermiticity channel
    cone: tuple
    mass_table: tuple
    hermiticity: tuple
    deep_generators: object
    deep_mass: object
    # H / global
    exact_no_float: bool
    scope: dict


def measure(deep: bool) -> Facts:
    main_head = git_output("rev-parse", "origin/main")
    authority = authority_certificate(main_head)
    exact: list = []

    # -----------------------------------------------------------------------
    # the committed constructions, imported and never re-derived
    # -----------------------------------------------------------------------
    differentials, star = b145.connection(SHEAR_X, SHEAR_T)
    edges_symbolic = b145.edge_differentials(
        differentials, star, HEALING_WEIGHTS
    )
    edge = {
        key: sp.expand(edges_symbolic[key].xreplace(ATLAS))
        for key in EDGE_KEYS
    }
    probe = edge[PROBE_EDGE]

    carriers = (
        ("flat", b159.flat_field()),
        ("counterpoint", b159.counterpoint_field()),
        ("control A", b159.control_field_a()),
        ("control B", b159.control_field_b()),
    )
    covers = {
        name: b145.cover_hodge_from_field(field) for name, field in carriers
    }
    flat_cover = covers["flat"]
    flat_hq = b145.quotient(flat_cover)

    mid = b142.descend(cover_move(MID_LABEL))
    mid_prime = b142.descend(cover_move(MID_PRIME_LABEL))
    operators = (
        ("theta", THETA),
        ("theta'", THETA_PRIME_OP),
        ("mid", mid),
        ("mid'", mid_prime),
    )

    # ---------------------------------------------------------------- B ----
    table = []
    for hname, rows in HALVES:
        for oname, operator in operators:
            tag = exchange_tag(operator, rows)
            pairing = half_pairing(operator, flat_hq, rows)
            value = (
                EXCHANGING_INERTIA if zero(pairing)
                else congruence_inertia(pairing)
            )
            table.append((hname, oname, tag, value))
    exch_rows = tuple(row for row in table if row[2] == "EXCH")
    pres_rows = tuple(row for row in table if row[2] == "PRES")
    raw_prime = sp.expand(
        half_selector(COMMITTED_ROWS).T
        * THETA_PRIME_OP
        * residue(probe, flat_cover)
        * half_selector(COMMITTED_ROWS)
    )
    calibration = (
        flat_cover == sp.eye(SIZE),
        flat_hq == sp.eye(PHYS),
        len(table),
        len(exch_rows),
        len(pres_rows),
        len(table) - len(exch_rows) - len(pres_rows),
        tuple(sorted({row[3] for row in exch_rows})),
        tuple(sorted({row[3] for row in pres_rows})),
        not zero(raw_prime)
        and zero(
            half_pairing(
                THETA_PRIME_OP, residue(probe, flat_cover), COMMITTED_ROWS
            )
        ),
        tuple(b145.in_admissible_cone(field) for _, field in carriers),
        sum(1 for entry in probe if entry != 0),
    )
    exact.append(sum(probe))

    # the widened reflection census, built once and reused by C and B alike
    labels = tuple(
        (et, pt, ex, px)
        for et in (1, -1)
        for pt in range(COVER_T)
        for ex in (1, -1)
        for px in range(LX)
    )
    descending = []
    for label in labels:
        operator = b142.descend(cover_move(label))
        if operator is not None:
            descending.append((label, operator))
    tag_census = collections.Counter()
    exch_wide = []
    for label, operator in descending:
        for hname, rows in HALVES_WIDE:
            tag = exchange_tag(operator, rows)
            tag_census[tag] += 1
            if tag == "EXCH":
                exch_wide.append((label, operator, hname, rows))

    volume = {
        (t, x): sp.Symbol(f"nu_{t}{x}", positive=True)
        for t in range(4)
        for x in range(4)
    }
    generic_flat = b145.cover_hodge_from_field(
        {cell: (sp.Integer(0), volume[cell]) for cell in volume}
    )
    generic_flat_hq = b145.quotient(generic_flat)
    free_nu_nonzero = sum(
        1
        for _label, operator, _hname, rows in exch_wide
        if not zero(sp.expand(half_pairing(operator, generic_flat_hq, rows)))
    )
    generic_diagonal = sp.diag(
        *[sp.Symbol(f"dg{k}", real=True) for k in range(PHYS)]
    )
    diagonal_control_nonzero = sum(
        1
        for _label, operator, _hname, rows in exch_wide
        if not zero(sp.expand(half_pairing(operator, generic_diagonal, rows)))
    )
    mechanism = True
    for _label, operator, _cell_half, cell_rows in exch_wide:
        complement = tuple(k for k in range(PHYS) if k not in cell_rows)
        for a in cell_rows:
            support = [k for k in range(PHYS) if operator[a, k] != 0]
            mechanism = (
                mechanism and len(support) == 1 and support[0] in complement
            )
    diagonality = (
        generic_flat.is_diagonal(),
        generic_flat_hq.is_diagonal(),
        len(volume),
        free_nu_nonzero,
        len(exch_wide),
        diagonal_control_nonzero,
        mechanism,
    )
    exact.append(sum(generic_flat_hq))

    # ---------------------------------------------------------------- C ----
    lam, mu = sp.symbols("lam mu", real=True)
    hop_a = single_hop(
        20, 24,
        sp.Symbol("uu1", real=True) + sp.I * sp.Symbol("vv1", real=True),
    )
    hop_b = single_hop(
        12, 16,
        sp.Symbol("uu2", real=True) + sp.I * sp.Symbol("vv2", real=True),
    )
    generic_real = sp.Matrix(
        SIZE, SIZE, lambda p, q: sp.Symbol(f"g{SIZE * p + q}", real=True)
    )
    real_linear = zero(
        sp.expand(
            residue(sp.expand(lam * hop_a + mu * hop_b), flat_cover)
            - lam * residue(hop_a, flat_cover)
            - mu * residue(hop_b, flat_cover)
        )
    )
    complex_linear_hop = zero(
        sp.expand(
            residue(sp.expand(sp.I * hop_a), flat_cover)
            - sp.I * residue(hop_a, flat_cover)
        )
    )
    complex_linear_generic = zero(
        sp.expand(
            residue(sp.expand(sp.I * generic_real), flat_cover)
            - sp.I * residue(generic_real, flat_cover)
        )
    )

    real_parts = sp.symbols("u0:1024", real=True)
    imaginary_parts = sp.symbols("v0:1024", real=True)
    generic_operator = sp.Matrix(
        SIZE,
        SIZE,
        lambda p, q: real_parts[SIZE * p + q]
        + sp.I * imaginary_parts[SIZE * p + q],
    )
    generic_residue = residue(generic_operator, flat_cover)

    def reaching_names(operator, rows):
        pairing = half_pairing(operator, generic_residue, rows)
        names = set()
        for entry in pairing:
            names |= sp.expand(entry).free_symbols
        return names

    committed_names = reaching_names(THETA, COMMITTED_ROWS)
    real_reaching = {
        int(str(s)[1:]) for s in committed_names if str(s).startswith("u")
    }
    imaginary_reaching = {
        int(str(s)[1:]) for s in committed_names if str(s).startswith("v")
    }
    linearity = (
        real_linear,
        complex_linear_hop,
        complex_linear_generic,
        2 * len(real_parts),
        len(real_parts),
        len(real_reaching),
        len(imaginary_reaching),
        len(real_reaching | imaginary_reaching),
        len(imaginary_reaching - real_reaching),
        len(real_reaching - imaginary_reaching),
    )

    per_half: dict = {}
    for _label, operator, hname, rows in exch_wide:
        names = reaching_names(operator, rows)
        indices = {int(str(s)[1:]) for s in names}
        key = tuple(sorted({displacement(k) for k in indices}))
        per_half.setdefault(hname, collections.Counter())[key] += 1
    law = []
    for hname, _rows in HALVES_WIDE:
        counter = per_half[hname]
        classes = next(iter(counter))
        law.append(
            (
                hname,
                sum(counter.values()),
                len(counter),
                tuple(sorted({c[0] for c in classes})),
                len(classes),
            )
        )
    contiguous_names = tuple(name for name, _rows in HALVES)
    committed_cell = collections.Counter(
        displacement(k) for k in (real_reaching | imaginary_reaching)
    )
    dead = tuple(
        sorted(
            (dt, dx)
            for dt in range(COVER_T)
            for dx in range(LX)
            if (dt, dx) not in committed_cell
        )
    )
    crossers = set()
    for k in real_reaching | imaginary_reaching:
        p, q = divmod(k, SIZE)
        crossers.add((cover_site(p)[0], cover_site(q)[0]))
    support_law = (
        len(descending),
        len(labels),
        tuple(sorted(tag_census.items())),
        len(exch_wide),
        tuple(law),
        len(dead),
        dead == tuple(sorted((dt, dx) for dt in (0, 4) for dx in range(LX))),
        all(((s % 4) in (0, 1)) != ((t % 4) in (0, 1)) for t, s in crossers),
    )

    spatial = {(0, 1), (0, 3)}
    temporal = {(1, 0), (7, 0)}
    committed_classes = (
        len(spatial & set(committed_cell)),
        len(temporal & set(committed_cell)),
        committed_cell[(1, 0)],
        committed_cell[(7, 0)],
        committed_cell[(1, 1)],
        committed_cell[(2, 0)],
        tuple(sorted(committed_cell.items())),
    )

    # ---------------------------------------------------------------- D ----
    nonzero_rows = []
    for key in EDGE_KEYS:
        residue_edge = residue(edge[key], flat_cover)
        for oname, operator in operators:
            for hname, rows in HALVES:
                if exchange_tag(operator, rows) != "EXCH":
                    continue
                pairing = half_pairing(operator, residue_edge, rows)
                if zero(pairing):
                    continue
                nonzero_rows.append(
                    (
                        key,
                        oname,
                        hname,
                        pairing.rank(),
                        congruence_inertia(pairing),
                    )
                )
    by_reflection = collections.Counter(row[1] for row in nonzero_rows)
    inertia_census = collections.Counter(row[4] for row in nonzero_rows)
    census = (
        len(nonzero_rows),
        EDGE_COUNT * EXCHANGING_CELLS,
        tuple(sorted({row[3] for row in nonzero_rows})),
        tuple(sorted(inertia_census.items(), key=str)),
        tuple(sorted(by_reflection.items())),
        sum(
            1 for row in nonzero_rows if row[1] in ("theta'", "mid'")
        ),
    )

    witness_mask = crossing_operator((0, 2), lambda x: -sp.I)
    witness_slots = tuple(
        (p, q)
        for p in range(SIZE)
        for q in range(SIZE)
        if witness_mask[p, q] != 0
    )
    deletion_rows = []
    for key in EDGE_KEYS:
        if any(edge[key][p, q] == 0 for p, q in witness_slots):
            deletion_rows.append((key, None, None))
            continue
        deleted = restrict(edge[key], witness_mask)
        pairing = clean(
            half_pairing(THETA, residue(deleted, flat_cover), COMMITTED_ROWS)
        )
        deletion_rows.append(
            (
                key,
                sp.simplify(pairing[0, 0]),
                congruence_inertia(pairing),
            )
        )
    psd_edges = tuple(
        row[0] for row in deletion_rows if row[2] == WITNESS_INERTIA
    )
    nsd_edges = tuple(
        row[0] for row in deletion_rows if row[2] == PROBE_DELETION_INERTIA
    )
    deletion = (
        len(deletion_rows),
        sum(1 for row in deletion_rows if row[2] is None),
        psd_edges,
        len(psd_edges),
        len(nsd_edges),
        tuple(
            row[1] for row in deletion_rows if row[2] == WITNESS_INERTIA
        ),
    )
    exact.append(sum(row[1] for row in deletion_rows if row[1] is not None))

    symbolic_pairing = half_pairing(
        THETA, residue(edges_symbolic[PROBE_EDGE], flat_cover), COMMITTED_ROWS
    )
    symbolic_pairing = sp.Matrix(
        HALF_DIM,
        HALF_DIM,
        lambda i, j: sp.simplify(symbolic_pairing[i, j]),
    )
    symbolic_form = (
        not zero(symbolic_pairing),
        symbolic_pairing.free_symbols == {SHEAR_T},
        zero(sp.expand(symbolic_pairing.xreplace({SHEAR_T: 0}))),
        tuple(symbolic_pairing[i, i] for i in range(HALF_DIM)),
    )
    exact.append(sum(symbolic_pairing))

    # ---------------------------------------------------------------- E ----
    antiperiodic = all(
        sp.expand(probe[PHYS + p, PHYS + q] - probe[p, q]) == 0
        and sp.expand(probe[PHYS + p, q] - probe[p, PHYS + q]) == 0
        for p in range(PHYS)
        for q in range(PHYS)
    )
    tied, tied_symbols, tied_representative = tied_family(probe)
    tied_residue = residue(tied, flat_cover)
    parameters = []
    for index in range(len(tied_symbols)):
        parameters += [
            sp.Symbol(f"r{'w'}{index}", real=True),
            sp.Symbol(f"s{'w'}{index}", real=True),
        ]
    committed_vector = sp.zeros(len(parameters), 1)
    for key, (index, (p, q)) in tied_representative.items():
        value = sp.expand(probe[p, q])
        committed_vector[2 * index, 0] = sp.re(value)
        committed_vector[2 * index + 1, 0] = sp.im(value)

    def vanishing_locus(operator):
        pairing = half_pairing(operator, tied_residue, COMMITTED_ROWS)
        rows_linear = []
        for entry in pairing:
            entry = sp.expand(entry)
            for part in (sp.re(entry), sp.im(entry)):
                part = sp.expand(part)
                if part != 0:
                    rows_linear.append(
                        [part.coeff(v, 1) for v in parameters]
                    )
        matrix = sp.Matrix(rows_linear)
        return pairing, matrix.rank(), zero(sp.expand(matrix * committed_vector))

    prime_pairing, prime_codim, prime_on = vanishing_locus(THETA_PRIME_OP)
    theta_pairing, theta_codim, theta_on = vanishing_locus(THETA)

    crossing = {}
    for key, (index, (p, q)) in tied_representative.items():
        if (
            sp.Symbol(f"rw{index}", real=True) in prime_pairing.free_symbols
            or sp.Symbol(f"sw{index}", real=True) in prime_pairing.free_symbols
        ):
            crossing[index] = (
                cover_site(p), cover_site(q), sp.simplify(probe[p, q])
            )
    crossing_weights = tuple(
        (
            x,
            tuple(
                sorted(
                    {
                        str(sp.simplify(weight))
                        for site, _source, weight in crossing.values()
                        if site[1] == x
                    }
                )
            ),
        )
        for x in range(LX)
    )
    crossing_classes = tuple(
        sorted(
            {
                (
                    (site[0] - source[0]) % COVER_T,
                    (site[1] - source[1]) % LX,
                )
                for site, source, _weight in crossing.values()
            }
        )
    )

    column_weight = [sp.Symbol(f"w{x}") for x in range(LX)]
    column_map = {
        "theta": {0: 0, 1: 3, 2: 2, 3: 1},
        "theta'": {0: 1, 1: 0, 2: 3, 3: 2},
    }
    formula_ok, conjugate_kills, generic_lives = True, True, True
    for name, operator in (("theta", THETA), ("theta'", THETA_PRIME_OP)):
        pairing = sp.expand(
            half_pairing(
                operator,
                residue(
                    crossing_operator(
                        range(LX), lambda x: column_weight[x]
                    ),
                    flat_cover,
                ),
                COMMITTED_ROWS,
            )
        )
        entries = {
            sp.simplify(pairing[i, j])
            for i in range(HALF_DIM)
            for j in range(HALF_DIM)
            if sp.simplify(pairing[i, j]) != 0
        }
        predicted = {
            sp.simplify(
                sp.I
                * (
                    column_weight[column_map[name][x]]
                    - sp.conjugate(column_weight[x])
                )
                / 2
            )
            for x in range(LX)
        }
        predicted |= {sp.simplify(-value) for value in predicted}
        formula_ok = formula_ok and entries <= predicted
        generic_lives = generic_lives and not zero(pairing)
        conjugate = {}
        for x in range(LX):
            partner = column_map[name][x]
            if partner == x:
                conjugate[column_weight[x]] = sp.Symbol(f"q{name}{x}", real=True)
            elif partner > x:
                base = (
                    sp.Symbol(f"c{name}{x}", real=True)
                    + sp.I * sp.Symbol(f"e{name}{x}", real=True)
                )
                conjugate[column_weight[x]] = base
                conjugate[column_weight[partner]] = sp.conjugate(base)
        conjugate_kills = conjugate_kills and zero(
            sp.expand(sp.expand_complex(sp.expand(pairing.xreplace(conjugate))))
        )

    staggered = {
        x: (2 * sp.I / 5 if x % 2 == 0 else -2 * sp.I / 5) for x in range(LX)
    }
    committed_crossing = crossing_operator(range(LX), lambda x: staggered[x])
    prime_committed_zero = zero(
        sp.expand(
            half_pairing(
                THETA_PRIME_OP,
                residue(committed_crossing, flat_cover),
                COMMITTED_ROWS,
            )
        )
    )
    theta_committed_zero = zero(
        sp.expand(
            half_pairing(
                THETA,
                residue(committed_crossing, flat_cover),
                COMMITTED_ROWS,
            )
        )
    )
    unstaggered = sp.Matrix(probe)
    for p in range(SIZE):
        for q in range(SIZE):
            if (
                unstaggered[p, q] != 0
                and cover_site(p)[1] == cover_site(q)[1]
                and cover_site(p)[1] % 2 == 1
            ):
                unstaggered[p, q] = -unstaggered[p, q]
    unstaggered_lives = not zero(
        half_pairing(
            THETA_PRIME_OP, residue(unstaggered, flat_cover), COMMITTED_ROWS
        )
    )
    conspiracy = (
        antiperiodic,
        len(tied_symbols),
        len(parameters),
        zero(sp.expand(tied_residue + tied_residue.H)),
        len(crossing),
        crossing_weights,
        crossing_classes,
        formula_ok,
        conjugate_kills,
        generic_lives,
        prime_committed_zero,
        theta_committed_zero,
        unstaggered_lives,
    )
    exact.append(sum(committed_crossing))

    loci = (
        prime_codim,
        theta_codim,
        len(parameters),
        prime_on,
        theta_on,
        not zero(prime_pairing) and prime_pairing.rank() == HALF_DIM,
    )

    # ---------------------------------------------------------------- F ----
    witness_residue = residue(witness_mask, flat_cover)
    witness_pairing = clean(
        half_pairing(THETA, witness_residue, COMMITTED_ROWS)
    )
    witness_live = sub_block(witness_pairing, LIVE, LIVE)
    restricted_probe = restrict(probe, witness_mask)
    ratios = {
        sp.simplify(witness_mask[p, q] / restricted_probe[p, q])
        for p, q in witness_slots
    }
    probe_deletion = clean(
        half_pairing(
            THETA, residue(restricted_probe, flat_cover), COMMITTED_ROWS
        )
    )
    witness = (
        len(witness_slots),
        tuple(sorted({displacement(SIZE * p + q) for p, q in witness_slots})),
        all(probe[p, q] != 0 for p, q in witness_slots),
        witness_pairing == sp.diag(1, 0, 1, 0, 1, 0, 1, 0),
        witness_pairing.rank(),
        congruence_inertia(witness_pairing),
        live_count(witness_live),
        witness_live.rank(),
        congruence_inertia(witness_live),
        tuple(str(value) for value in sorted(ratios, key=str)),
        congruence_inertia(probe_deletion),
        zero(
            sp.expand(
                half_pairing(
                    THETA,
                    residue(witness_mask, flat_cover, MASS),
                    COMMITTED_ROWS,
                )
                - witness_pairing
            )
        ),
        b145.in_admissible_cone(b159.flat_field()),
    )
    exact.append(sum(witness_pairing))

    generic_witness_support = crossing_operator(
        (0, 2), lambda x: sp.Symbol(f"gw{x}")
    )
    full_class = sp.zeros(SIZE, SIZE)
    class_hops = 0
    for t in range(COVER_T):
        for x in range(LX):
            full_class[cover_index(t, x), cover_index(t + 1, x)] = sp.Symbol(
                f"fc{class_hops}"
            )
            class_hops += 1
    generic_antiperiodic, _s, _r = tied_family(
        sp.ones(SIZE, SIZE), tag="ap"
    )
    generic_free = sp.Matrix(
        SIZE, SIZE, lambda p, q: sp.Symbol(f"z{SIZE * p + q}")
    )
    antiperiodic_residue = residue(generic_antiperiodic, flat_cover)
    free_residue = residue(generic_free, flat_cover)
    source_slices = {cover_site(q)[0] for _p, q in witness_slots}
    target_slices = {cover_site(p)[0] for p, _q in witness_slots}
    vacuous = (
        zero(sp.expand(generic_witness_support * generic_witness_support)),
        zero(sp.expand(full_class * full_class)),
        class_hops,
        zero(sp.expand(antiperiodic_residue + antiperiodic_residue.H)),
        zero(sp.expand(free_residue + free_residue.H)),
        tuple(sorted(source_slices)),
        tuple(sorted(target_slices)),
        source_slices.isdisjoint(target_slices),
    )

    cell_rows = []
    for oname, operator in operators:
        for hname, rows in HALVES_WIDE:
            if exchange_tag(operator, rows) != "EXCH":
                continue
            pairing = clean(half_pairing(operator, witness_residue, rows))
            cell_rows.append(
                (
                    oname,
                    hname,
                    EXCHANGING_INERTIA if zero(pairing)
                    else congruence_inertia(pairing),
                )
            )
    cell_census = collections.Counter(row[2] for row in cell_rows)
    cells = (
        len(cell_rows),
        tuple(sorted(cell_census.items(), key=str)),
        sum(1 for row in cell_rows if row[2] == WITNESS_INERTIA),
        tuple(
            row[:2] for row in cell_rows if row[2] == WITNESS_INERTIA
        ),
    )

    live_rows = []
    for name, _field in carriers:
        residue_carrier = residue(probe, covers[name])
        entry = [name]
        for _oname, operator in (("theta", THETA), ("theta'", THETA_PRIME_OP)):
            block = sub_block(
                half_pairing(operator, residue_carrier, COMMITTED_ROWS),
                LIVE,
                LIVE,
            )
            entry += [live_count(block), block.rank()]
        live_rows.append(tuple(entry))
    occupancy = tuple(
        live_count(
            sub_block(
                half_pairing(
                    THETA, residue(edge[key], flat_cover), COMMITTED_ROWS
                ),
                LIVE,
                LIVE,
            )
        )
        for key in EDGE_KEYS
    )
    prime_occupancy = tuple(
        live_count(
            sub_block(
                half_pairing(
                    THETA_PRIME_OP,
                    residue(edge[key], flat_cover),
                    COMMITTED_ROWS,
                ),
                LIVE,
                LIVE,
            )
        )
        for key in EDGE_KEYS
    )
    live_reversal = (
        tuple((row[0], row[1]) for row in live_rows),
        tuple(row[2] for row in live_rows),
        tuple(row[3] for row in live_rows),
        tuple(row[4] for row in live_rows),
        occupancy,
        prime_occupancy,
        witness_live.rank(),
    )

    odd_x = clean(
        half_pairing(
            THETA,
            residue(crossing_operator((1, 3), lambda x: -sp.I), flat_cover),
            COMMITTED_ROWS,
        )
    )
    uniform = clean(
        half_pairing(
            THETA,
            residue(crossing_operator(range(LX), lambda x: -sp.I), flat_cover),
            COMMITTED_ROWS,
        )
    )
    opposite = clean(
        half_pairing(
            THETA,
            residue(
                crossing_operator(
                    (0, 2), lambda x: -sp.I if x == 0 else sp.I
                ),
                flat_cover,
            ),
            COMMITTED_ROWS,
        )
    )
    even_generic = clean(
        half_pairing(
            THETA,
            residue(
                crossing_operator((0, 2), lambda x: column_weight[x]),
                flat_cover,
            ),
            COMMITTED_ROWS,
        )
    )
    even_diagonal = tuple(even_generic[i, i] for i in range(HALF_DIM))
    selectivity = (
        congruence_inertia(witness_pairing),
        congruence_inertia(odd_x),
        congruence_inertia(uniform),
        congruence_inertia(opposite),
        tuple(entry == 0 for entry in odd_x.diagonal()),
        even_diagonal
        == (
            -sp.im(column_weight[0]), 0, -sp.im(column_weight[2]), 0,
            -sp.im(column_weight[0]), 0, -sp.im(column_weight[2]), 0,
        ),
    )

    # ---------------------------------------------------------------- G ----
    free_cover = b145.cover_hodge_general(
        b145.NU_MODULUS, b145.A_MODULUS, b145.B_MODULUS, b145.INV_MODULUS
    )
    cone_pairing = half_pairing(
        THETA, residue(witness_mask, free_cover), COMMITTED_ROWS
    )
    cone_pairing = sp.Matrix(
        HALF_DIM, HALF_DIM, lambda i, j: sp.simplify(cone_pairing[i, j])
    )
    shear_symbols = set(b145.SHEAR_COORDS)
    present = set()
    for entry in cone_pairing:
        present |= entry.free_symbols
    even_even = tuple(b145.B_MODULUS[cell] for cell in CONE_SHEAR_CELLS)
    off_diagonal = tuple(
        (i, j)
        for i in range(HALF_DIM)
        for j in range(HALF_DIM)
        if i < j and cone_pairing[i, j] != 0
    )
    faces_zero_diagonal = all(
        cone_pairing[i, i] == 0 or cone_pairing[j, j] == 0
        for i, j in off_diagonal
    )
    positive_diagonal = tuple(
        cone_pairing[i, i]
        for i in range(HALF_DIM)
        if cone_pairing[i, i] != 0
        and not (cone_pairing[i, i].free_symbols & shear_symbols)
    )
    killed = cone_pairing.xreplace({s: 0 for s in even_even})
    unit = {s: sp.Integer(1) for s in present if s not in shear_symbols}
    shear_symbol, volume_symbol = sp.symbols("sg nu_cell", real=True)
    _n, _a, b_value, _m = b145.moduli_from_field(
        {(0, 0): (shear_symbol, volume_symbol)}
    )
    cone = (
        tuple(sorted(map(str, present & shear_symbols))),
        tuple(sorted(map(str, present & set(b145.ODD_SHEAR_COORDS)))),
        len(positive_diagonal),
        off_diagonal,
        faces_zero_diagonal,
        congruence_inertia(clean(killed.xreplace(unit))),
        sp.simplify(
            b_value[(0, 0)] * (1 - shear_symbol ** 2)
            + volume_symbol * shear_symbol
        )
        == 0,
        len(CONE_SHEAR_CELLS),
        CONE_COORDINATES - len(CONE_SHEAR_CELLS),
    )
    exact.append(sum(cone_pairing))

    def mass_row(field):
        cover = b145.cover_hodge_from_field(field)
        massless = congruence_inertia(
            clean(half_pairing(THETA, residue(witness_mask, cover), COMMITTED_ROWS))
        )
        massive = tuple(
            congruence_inertia(
                clean(
                    half_pairing(
                        THETA, residue(witness_mask, cover, m), COMMITTED_ROWS
                    )
                )
            )
            for m in MASSES
        )
        return massless, massive

    baseline_curved = (
        odd_time_field(R(1, 3), sp.Integer(1)),
        odd_time_field(R(3, 4), sp.Integer(3)),
    )
    baseline_rows = tuple(mass_row(field) for field in baseline_curved)
    flat_masses = tuple(
        congruence_inertia(
            clean(
                half_pairing(
                    THETA, residue(witness_mask, flat_cover, m), COMMITTED_ROWS
                )
            )
        )
        for m in (sp.Integer(0),) + MASSES
    )
    generic_flat_massless = half_pairing(
        THETA, residue(witness_mask, generic_flat), COMMITTED_ROWS
    )
    generic_flat_massive = half_pairing(
        THETA, residue(witness_mask, generic_flat, MASS), COMMITTED_ROWS
    )
    mass_table = (
        tuple(str(m) for m in MASSES),
        flat_masses,
        zero(sp.expand(generic_flat_massive - generic_flat_massless)),
        baseline_rows,
        sum(
            1
            for _massless, massive in baseline_rows
            for value in massive
            if value[2] == 0
        ),
        tuple(
            all(value == CURVED_MASSIVE_INERTIA for value in massive)
            for _massless, massive in baseline_rows
        ),
        tuple(massless for massless, _massive in baseline_rows),
    )

    witness_rows = b145.hermiticity_rows(
        b145.pairing(residue(witness_mask, free_cover, MASS))
    )
    committed_rows_hermiticity = b145.hermiticity_rows(
        b145.pairing(residue(probe, free_cover, MASS))
    )
    hermiticity = (
        b145.row_basis(witness_rows).rows,
        b145.row_basis(committed_rows_hermiticity).rows,
        len(witness_rows),
        len(committed_rows_hermiticity),
    )

    # ------------------------------------------------------------- deep ----
    deep_generators = None
    deep_mass = None
    if deep:
        explicit_real, explicit_imaginary = set(), set()
        for index in range(SIZE * SIZE):
            p, q = divmod(index, SIZE)
            for target, value in (
                (explicit_real, sp.Integer(1)),
                (explicit_imaginary, sp.I),
            ):
                if not zero(
                    half_pairing(
                        THETA,
                        residue(single_hop(p, q, value), flat_cover),
                        COMMITTED_ROWS,
                    )
                ):
                    target.add(index)
        deep_generators = (
            2 * SIZE * SIZE,
            len(explicit_real),
            len(explicit_imaginary),
            len(explicit_real | explicit_imaginary),
            len(explicit_imaginary - explicit_real),
            explicit_real == real_reaching,
            explicit_imaginary == imaginary_reaching,
        )
        deep_rows, flat_members, curved_members = [], 0, 0
        for volume_value in (sp.Integer(1), R(1, 2), sp.Integer(3)):
            for shear_value in (
                sp.Integer(0), R(1, 3), R(-1, 3), R(3, 4)
            ):
                field = odd_time_field(shear_value, volume_value)
                if not b145.in_admissible_cone(field):
                    continue
                cover = b145.cover_hodge_from_field(field)
                massless, massive = mass_row(field)
                # the second, structurally different route: the full pairing
                # read as m [theta H_q]_++ + Herm[theta K]_++ rather than
                # through quotient_action's own mass term
                split = tuple(
                    congruence_inertia(
                        clean(
                            sp.expand(
                                m
                                * half_pairing(
                                    THETA, b145.quotient(cover), COMMITTED_ROWS
                                )
                                + half_pairing(
                                    THETA,
                                    residue(witness_mask, cover),
                                    COMMITTED_ROWS,
                                )
                            )
                        )
                    )
                    for m in MASSES
                )
                curved = any(value[0] != 0 for value in field.values())
                if curved:
                    curved_members += 1
                else:
                    flat_members += 1
                deep_rows.append(
                    (curved, massless, massive, massive == split)
                )
        deep_mass = (
            len(deep_rows),
            flat_members,
            curved_members,
            tuple(sorted({row[1] for row in deep_rows})),
            tuple(
                sorted(
                    {
                        value
                        for row in deep_rows
                        if row[0]
                        for value in row[2]
                    }
                )
            ),
            tuple(
                sorted(
                    {
                        value
                        for row in deep_rows
                        if not row[0]
                        for value in row[2]
                    }
                )
            ),
            all(row[3] for row in deep_rows),
            sum(
                1
                for row in deep_rows
                if row[0]
                for value in row[2]
                if value[2] == 0
            ),
        )

    exact_no_float = all(no_float(value) for value in exact)
    return Facts(
        main_head=main_head,
        authority=authority,
        calibration=calibration,
        diagonality=diagonality,
        linearity=linearity,
        support_law=support_law,
        committed_classes=committed_classes,
        census=census,
        deletion=deletion,
        symbolic_form=symbolic_form,
        conspiracy=conspiracy,
        loci=loci,
        witness=witness,
        vacuous=vacuous,
        cells=cells,
        live_reversal=live_reversal,
        selectivity=selectivity,
        cone=cone,
        mass_table=mass_table,
        hermiticity=hermiticity,
        deep_generators=deep_generators,
        deep_mass=deep_mass,
        exact_no_float=exact_no_float,
        scope=scope_certificate(raw_note()),
    )


