def scope_certificate(note_text: str) -> dict:
    note = normalized_note(note_text)
    compact = compact_note(note_text)
    return {
        "scout_discipline": "scout" in note,
        "measured_never_registered": "measured" in note
        and "never registered" in note,
        "premise_class_change": "premise-class" in note,
        "pre_registered_rule": "pre-registered" in note,
        "committed_edges_settle": "52 of 128" in note,
        "rank_eight_census": "(6,0,2)" in compact and "(2,0,6)" in compact,
        "pure_link_deletion": "link deletion" in note,
        "six_committed_edges": "six of the sixteen" in note,
        "even_x_crossings": "even-x" in note,
        "reweighted_witness_second": "reweighting" in note,
        "witness_ratio": "-5/2" in compact,
        "diagonality_theorem": "diagonality" in note,
        "mass_channel_irreparable": "irreparable" in note,
        "conjugate_weights": "conjugate weights" in note,
        "crossing_entry_formula": "conj(w(x))" in compact,
        "staggered_weights": "2i/5" in compact,
        "codimension_eight": "codimension 8" in note,
        "theta_does_not_annihilate": "does not annihilate" in note,
        "support_law": "support law" in note,
        "spatial_no_go": "never reach" in note,
        "temporal_classes_reach": "temporal classes" in note,
        "far_corner_unnecessary": "far-corner" in note
        and "unnecessary" in note,
        "r_linear_not_c_linear": "r-linear" in note
        and "not c-linear" in note,
        "two_thousand_generators": "2048" in note,
        "imaginary_only_hops": "imaginary part only" in note,
        "completeness_scope": "not exhausted" in note,
        # --- the Block 159 narrowing section ---------------------------------
        "narrowing_note": "narrowing note" in note,
        "w1_core_survives": "core survives" in note,
        "refuted_generalisation_hops": (
            "only a change to which hops exist can" in note
        ),
        "refuted_generalisation_reflection": (
            "not an artifact of the reflection" in note
        ),
        "r1_narrowed": re.search(r"\br1\b", note) is not None,
        "landed_claim_scope": "claim_scope" in note,
        # --- the overlap answers ---------------------------------------------
        "live_sector_reached": "live sector" in note,
        "theta_prime_property": "theta-prime property" in note,
        "support_change_retired": "retired" in note,
        "sign_lock": "sign lock" in note,
        "even_time_even_x": "even-time, even-x" in note,
        "odd_shears_free": "odd shears" in note,
        "codimension_four": "codimension 4" in note,
        "b154_codimension_two": "codimension 2" in note,
        "thinner_than_the_sliver": "thinner" in note and "sliver" in note,
        "escape_from_emptiness": "emptiness" in note,
        "massless_only_on_curved": "massless" in note,
        "flat_at_every_mass": "every mass" in note,
        # --- the certificate and its vacuous items ---------------------------
        "vacuous_items": "vacuous" in note,
        "disjoint_slices": "disjoint" in note,
        "not_nilpotent_control": "not nilpotent" in note,
        "one_of_sixteen_cells": "1 of 16" in note,
        "b145_interface": "block 145" in note,
        # --- the open obstruction --------------------------------------------
        "x_selectivity": "x-selectivity" in note,
        "x_translation_covariant": "x-translation-covariant" in note,
        "open_obstruction": "open obstruction" in note,
        "block_161": "block 161" in note,
        "pool_two": "pool 2" in note,
        # --- discipline and disclosures --------------------------------------
        "checker_credit": "checker" in note,
        "quoted_then_corrected": "quoted" in note,
        "common_mode": "common-mode" in note,
        "cross_context": "cross-context" in note,
        "sample_not_cone_wide": "not a cone-wide" in note or "sample" in note,
        "os_no_go": "not an os no-go" in note,
        "curved_os_no_go": "not a curved os no-go" in note,
        "axiom": "no axiom amendment is justified" in note,
        "zero_retirement": "zero obligation retirement" in note,
        "zero_score": (
            "no toe percentage moves" in note
            or "no toe percentage movement" in note
        ),
        "zero_e2e": (
            "retained-positive end-to-end theory count remains zero" in note
        ),
        "n1_n8": all(
            re.search(rf"\bn{index}\b", note) is not None
            for index in range(1, 9)
        ),
        "w1": re.search(r"\bw1\b", note) is not None,
        # Raw substring membership makes the printed fence byte-identical to its
        # note occurrence.
        "n5_verbatim": N5_FENCE in note_text,
        # NEGATIVE key.  The note must NOT be written up as any kind of priority
        # claim about curved positivity; the gate greps the NORMALIZED note, so
        # the banned wording may not appear anywhere, not even inside a
        # prohibition list, and the note describes it instead of spelling it.
        "no_priority_claim": (
            "first curved" not in note
            and "novel" not in note
            and "unprecedented" not in note
        ),
        # The LaTeX rho guard: a line-wrapped \rho leaves a stray "ho_" at the
        # start of a line and silently mangles a modulus name.
        "rho_guard": "\nho_" not in note_text,
    }


